mapper.select:
select *
from app_permission
where permission_code = #{permissionCode}

    and status = #{status}

order by id asc
limit 1

select *
from app_permission
where module_code = #{moduleCode}
  and status = #{status}
order by permission_code asc, id asc

select *
from app_permission
where permission_code in

    #{code}

  and status = #{status}
order by permission_code asc, id asc

select exists(
    select 1
    from app_permission
    where permission_code = #{permissionCode}
      and status = #{status}
)

select * from app_permission where id in
#{id}
order by id asc
